function openBusinessEditor(id=null){if(!canPost())return;const b=id?bizById(id):state.myBiz;if(b&&b.mine!==true&&b!==state.myBiz)return;editor={kind:'biz',id:b?.id||null,photos:[...(b?.photos||[])]};editorDirty=false;showDialog(b?.live?'Editar página':'Criar página do negócio',`<div class="form-grid">${field('biz-name','Nome do negócio',b?.name||'','required minlength="3" maxlength="100" class="full"')}${selectField('biz-category','Tipo de serviço',[['','Escolher'],...GROUP_NAMES],b?.cat||'','required')}${field('biz-hours','Horário ou agendamento',b?.hours||'','required maxlength="100"')}<div class="full" id="biz-specs-wrap">${specChips(b?.cat,b?.specs)}</div>${chipEntry('biz-hoods','Bairros em que atende',b?.hoods||[],'Digite um bairro e toque Enter.')}${chipEntry('biz-services','Serviços',b?.svc||[],'Digite um serviço e toque Enter.')}${field('biz-bio','Apresentação',b?.bio||'','type="textarea" rows="3" maxlength="1500" class="full"')}${field('biz-discount','Benefício para a comunidade (opcional)',b?.disc||'','maxlength="120" class="full"')}${field('biz-whatsapp','WhatsApp (opcional)',b?.whatsapp||'','type="tel" inputmode="tel" autocomplete="tel" supporting-text="DDD e número."')}${field('biz-instagram','Instagram (opcional)',b?.instagram||'','supporting-text="Nome do perfil, sem @."')}${field('biz-website','Site (opcional)',b?.website||'','type="url" class="full"')}${photoUploadHtml()}</div>`,`${btn('Cancelar','close-dialog','','text')}${btn(b?.live?'Salvar alterações':'Criar minha página','submit-biz','','filled')}`,'editor');$('#biz-category')?.addEventListener('change',e=>{$('#biz-specs-wrap').innerHTML=specChips(e.target.value,[]);});$('#biz-specs-wrap')?.addEventListener('click',()=>{editorDirty=true;});}
async function submitBusiness(){if(!editor||!canPost()||!validFields(['biz-name','biz-category','biz-hours','biz-website']))return;const website=$('#biz-website').value.trim(),phone=$('#biz-whatsapp').value.replace(/\D/g,''),insta=$('#biz-instagram').value.trim().replace(/^@/,'');if(phone&&!/^\d{10,15}$/.test(phone)){notify('Confira o DDD e o número do WhatsApp.','error');return;}if(insta&&!/^[a-zA-Z0-9._]{1,30}$/.test(insta)){notify('Informe o nome válido do perfil do Instagram.','error');return;}if(website&&!/^https?:\/\//i.test(website)){notify('O site deve começar com https:// ou http://.','error');return;}const data={name:$('#biz-name').value.trim(),cat:$('#biz-category').value,specs:[...document.querySelectorAll('#biz-specs md-filter-chip')].filter(c=>c.selected&&groupSpecs($('#biz-category').value).includes(c.dataset.spec)).map(c=>c.dataset.spec),hours:$('#biz-hours').value.trim(),hoods:chipValues('biz-hoods'),svc:chipValues('biz-services'),bio:$('#biz-bio').value.trim(),disc:$('#biz-discount').value.trim(),whatsapp:phone,instagram:insta,website,photos:[...editor.photos]};if(!GROUP_NAMES.includes(data.cat)){notify('Escolha o tipo de serviço do negócio.','error');return;}if(!data.hoods.length){notify('Adicione pelo menos um bairro.','error');$('#biz-hoods-entry')?.focus();return;}if(!data.svc.length){notify('Adicione pelo menos um serviço.','error');$('#biz-services-entry')?.focus();return;}const id=editor.id||uid('b'),old=state.myBiz?.id===id?state.myBiz:null;const ok=mutate(()=>{state.myBiz={...(old||{id,recN:0,says:[],views:0,icon:'storefront',saved:false,...(state.bizSuspended?{suspended:true}:{})}),...data,mine:true,live:true,claimed:true,city:state.homeCity,ini:initals(data.name),owner:`${state.profile.name}, perfil de teste verificado`,demo:data.photos.some(p=>!p.startsWith('data:'))};},{redraw:false});if(ok){await closeDialog(true);navigate('negocio',id);notify(old?'Página atualizada':'Página criada');}}

// Chips de entrada (Rodada 10): cada valor vira um md-input-chip removível; o texto
// digitado e não confirmado com Enter também entra ao publicar.
function chipEntry(id,label,values,hint){return `<div class="chip-entry full" data-chip-entry="${id}"><md-chip-set id="${id}-chips" aria-label="${esc(label)}">${values.map(v=>chipEntryChip(v)).join('')}</md-chip-set>${field(id+'-entry',label,'',`supporting-text="${esc(hint)}" maxlength="60"`)}</div>`;}
function chipEntryChip(v){return `<md-input-chip label="${esc(v)}" remove-only data-chip-value="${esc(v)}"></md-input-chip>`;}
function chipValues(id){chipEntryCommit(id);return [...document.querySelectorAll(`#${id}-chips md-input-chip`)].map(c=>c.dataset.chipValue);}
function chipEntryCommit(id){const entry=$(`#${id}-entry`),set=$(`#${id}-chips`);if(!entry||!set)return;const parts=entry.value.split(/[,\n]/).map(x=>x.trim()).filter(Boolean);entry.value='';for(const v of parts){if([...set.children].some(c=>norm(c.dataset.chipValue)===norm(v)))continue;set.insertAdjacentHTML('beforeend',chipEntryChip(v));editorDirty=true;}}
function bindChipEntries(scope){for(const box of scope.querySelectorAll('[data-chip-entry]')){const id=box.dataset.chipEntry,entry=$(`#${id}-entry`);entry?.addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Enter'||e.key===','){e.preventDefault();chipEntryCommit(id);}});entry?.addEventListener('paste',()=>setTimeout(()=>{if(/[,\n]/.test(entry.value))chipEntryCommit(id);}));box.addEventListener('remove',()=>{editorDirty=true;setTimeout(()=>entry?.focus());},true);}}
// Rodada 12: especialidades do grupo como chips de filtro; nenhuma marcada = atende o grupo todo.
function specChips(group,selected=[]){const specs=groupSpecs(group);return specs.length?`<p class="field-label">Especialidades (opcional)</p><md-chip-set id="biz-specs" aria-label="Especialidades">${specs.map(s=>`<md-filter-chip label="${esc(s)}" data-spec="${esc(s)}"${selected?.includes(s)?' selected':''}></md-filter-chip>`).join('')}</md-chip-set><p class="form-note">Sem marcar nenhuma, você recebe pedidos de todo o grupo.</p>`:'';}
